import 'package:flutter/material.dart';
import 'package:flutter_riverpod/flutter_riverpod.dart';
import '../../core/validators/app_validators.dart';
import '../../widgets/app_text_field.dart';
import 'auth_controller.dart';
class LoginScreen extends ConsumerStatefulWidget { const LoginScreen({super.key}); @override ConsumerState<LoginScreen> createState()=>_LoginScreenState(); }
class _LoginScreenState extends ConsumerState<LoginScreen> { final _form=GlobalKey<FormState>(); final _email=TextEditingController(),_password=TextEditingController(); @override void dispose(){_email.dispose();_password.dispose();super.dispose();} @override Widget build(BuildContext context){ final loading=ref.watch(authControllerProvider).isLoading; return Scaffold(body:SafeArea(child:Center(child:ConstrainedBox(constraints:const BoxConstraints(maxWidth:460),child:Padding(padding:const EdgeInsets.all(24),child:Form(key:_form,child:Column(mainAxisSize:MainAxisSize.min,crossAxisAlignment:CrossAxisAlignment.stretch,children:[Icon(Icons.school_rounded,size:64,color:Theme.of(context).colorScheme.primary),const SizedBox(height:16),Text('مرحبًا بعودتك',textAlign:TextAlign.center,style:Theme.of(context).textTheme.headlineMedium),const SizedBox(height:28),AppTextField(controller:_email,label:'البريد الإلكتروني',keyboardType:TextInputType.emailAddress,validator:AppValidators.email),const SizedBox(height:12),AppTextField(controller:_password,label:'كلمة المرور',obscureText:true,validator:AppValidators.password),Align(alignment:AlignmentDirectional.centerEnd,child:TextButton(onPressed:()=>Navigator.pushNamed(context,'/forgot-password'),child:const Text('نسيت كلمة المرور؟'))),FilledButton(onPressed:loading?null:() async {if(!_form.currentState!.validate())return; await ref.read(authControllerProvider.notifier).signIn(_email.text.trim(),_password.text);},child:loading?const CircularProgressIndicator():const Text('تسجيل الدخول')),TextButton(onPressed:()=>Navigator.pushNamed(context,'/register'),child:const Text('إنشاء حساب جديد'))]))))))); } }
